92	struct Allreduce<2> {
93	template<typename T, typename Operator>
94	static __device__ __forceinline__ T run(T x, Operator &op) {
95	    x = op(x, __shfl_xor_sync(uint32_t(-1), x, 1));
96	    return x;
97	}
98	};
