177	template <typename To_type, typename Engine, typename Layout>
178	CUTLASS_DEVICE auto convert_type_unsafe(Tensor<Engine, Layout> const &tensor) {
179	    using From_type = typename Engine::value_type;
180	    static constexpr int numel = decltype(size(tensor))::value;
181	    cutlass::NumericArrayConverter<To_type, From_type, numel> convert_op;
182	    // HACK: this requires tensor to be "contiguous"
183	    auto frag = convert_op(*reinterpret_cast<const cutlass::Array<From_type, numel> *>(tensor.data()));
184	    return make_tensor(make_rmem_ptr<To_type>(&frag), tensor.layout());
185	    // Unsafe because we're returning a tensor with memory allocated on the stack. If the compiler does not
186	    // inline this function, then the memory might not be valid.
187	}
