190	
191	template <typename Engine, typename Layout, typename EngineOut>
192	CUTLASS_DEVICE void convert_type_out(Tensor<Engine, Layout> const &tensor, Tensor<EngineOut, Layout> &out) {
193	    // Somehow if we allocate out inside this function and return it, e2e is slower and the output can be wrong.
194	    using From_type = typename Engine::value_type;
195	    using To_type = typename EngineOut::value_type;
196	    static constexpr int FragmentSize = std::max(sizeof(From_type) / sizeof(To_type), sizeof(To_type) / sizeof(From_type));
197	    static_assert(CUTE_STATIC_V(size(tensor)) % FragmentSize == 0, "Fragment size does not vectorize properly");
198	    Tensor frag = recast<cutlass::Array<From_type, FragmentSize> const>(tensor);
199	    Tensor out_frg = recast<cutlass::Array<To_type, FragmentSize>>(out);
200	    static_assert(size(frag) == size(out_frg));
201	    cutlass::NumericArrayConverter<To_type, From_type, FragmentSize> convert_op;
202	    #pragma unroll
203	    for (int i = 0; i < size(frag); ++i) { out_frg[i] = convert_op(frag[i]); }
204	}
