455	template <bool Is_even_MN=true, bool Is_even_K=true, bool Clear_OOB_MN=false, bool Clear_OOB_K=true,
456	          class CopyAtom, class TV, class Tiler, typename Engine0, typename Layout0, typename Engine1, typename Layout1,
457	          typename Engine2, typename Layout2, typename Engine3, typename Layout3>
458	CUTLASS_DEVICE void copy(TiledCopy<CopyAtom, TV, Tiler> const &tiled_copy, Tensor<Engine0, Layout0> const &S,
459	                         Tensor<Engine1, Layout1> &D, Tensor<Engine2, Layout2> const &identity_MN,
460	                         Tensor<Engine3, Layout3> const &predicate_K, const int max_MN=0) {
461	    // Decay TiledCopy to CopyAtom
462	    auto copy_atom = static_cast<CopyAtom const&>(tiled_copy);
463	    CUTE_STATIC_ASSERT_V(rank(S) == Int<3>{});
464	    CUTE_STATIC_ASSERT_V(rank(D) == Int<3>{});
465	    CUTE_STATIC_ASSERT_V(size<0>(S) == size<0>(D));                     // MMA
466	    CUTE_STATIC_ASSERT_V(size<1>(S) == size<1>(D));                     // MMA_M
467	    CUTE_STATIC_ASSERT_V(size<2>(S) == size<2>(D));                     // MMA_K
468	    // There's no case where !Clear_OOB_K && Clear_OOB_MN
469	    static_assert(!(Clear_OOB_MN && !Clear_OOB_K));
470	    auto has_with_bool = cute::is_valid([](auto t)->void_t<decltype(declval<typename decltype(t)::Traits>().with(true))>{}, copy_atom);
471	    #pragma unroll
472	    for (int m = 0; m < size<1>(S); ++m) {
473	        bool predicate_mn = Is_even_MN || get<0>(identity_MN(_0{}, m, _0{})) < max_MN;
474	        if constexpr (Is_even_MN || !Clear_OOB_MN) {
475	            if (Is_even_MN || predicate_mn) {
476	                #pragma unroll
477	                for (int k = 0; k < size<2>(S); ++k) {
478	                    if constexpr (Is_even_K || !Clear_OOB_K) {
479	                        if (Is_even_K || predicate_K(k)) { cute::copy(copy_atom, S(_, m, k), D(_, m, k)); }
480	                    } else {  // Clear_OOB_K == true && Is_even_K == false
481	                        // If copy traits can be transformed with a predicate value, do it, otherwise branch here
482	                        if constexpr (has_with_bool) {
483	                            cute::copy(copy_atom.with(predicate_K(k)), S(_, m, k), D(_, m, k));
484	                        } else {
485	                            if (predicate_K(k)) {
486	                                cute::copy(copy_atom, S(_, m, k), D(_, m, k));
487	                            } else {
488	                                cute::clear(D(_, m, k));
489	                            }
490	                        }
491	                    }
492	                }
493	            }
494	        } else {  // Clear_OOB_MN == true && Is_even_MN == false, also implies Clear_OOB_K == true
495	            if constexpr (!has_with_bool) {
496	                if (predicate_mn) {
497	                    #pragma unroll
498	                    for (int k = 0; k < size<2>(S); ++k) {
499	                        if (Is_even_K || predicate_K(k)) {
500	                            cute::copy(copy_atom, S(_, m, k), D(_, m, k));
501	                        } else if (Clear_OOB_K) {
502	                            cute::clear(D(_, m, k));
503	                        }
504	                    }
505	                } else {
506	                    cute::clear(D(_, m, _));
507	                }
508	            } else {  // combine the mn predicate with the k predicate
509	                #pragma unroll
510	                for (int k = 0; k < size<2>(S); ++k) {
511	                    cute::copy(copy_atom.with(predicate_mn && (Is_even_K || predicate_K(k))), S(_, m, k), D(_, m, k));
512	                }
513	            }
514	        }
515	    }
516	}
