520	// Byte permute and shuffle to match register layout of
521	// (FP8 downcasted) accumulator of GEMM-I to FP8 operand A of GEMM-II.
522	template <typename Fragment>
523	CUTLASS_DEVICE void permute_Aregs_fp8(Fragment &frag) {
524	    // frag has shape ((4, 2, 2), MMA_M, MMA_N), each element is 8 bits
525	    static_assert(decltype(size<0, 0>(frag))::value == 4);
526	    static_assert(decltype(size<0, 1>(frag))::value == 2);
527	    static_assert(decltype(stride<0, 0>(frag))::value == 1);
528	    static_assert(decltype(stride<0, 1>(frag))::value == 4);
529	    static_assert(sizeof(typename Fragment::value_type) == 1);
530	
531	    int quad_idx = threadIdx.x % 4;
532	    bool lane_03 = quad_idx == 0 || quad_idx == 3;
533	    int selector_upper = lane_03 ? 0x5410 : 0x1054;
534	    int selector_lower = lane_03 ? 0x7632 : 0x3276;
535	
536	    static constexpr int upper_map[4] = {0, 3, 1, 2};
537	    // static constexpr int lower_map[4] = {1, 2, 0, 3};
538	
539	    Tensor frag_64b = recast<uint2>(frag);  // ((1, 1, 2), MMA_M, MMA_N)
540	    #pragma unroll
541	    for (int i = 0; i < size(frag_64b); ++i) {
542	        uint32_t upper = frag_64b[i].x;
543	        uint32_t lower = frag_64b[i].y;
544	        uint32_t upper0 = lane_03 ? upper : lower;
545	        uint32_t lower0 = lane_03 ? lower : upper;
546	        upper0 = __shfl_sync(uint32_t(-1), upper0, upper_map[quad_idx], 4);
547	        // lower0 = __shfl_sync(uint32_t(-1), lower0, lower_map[quad_idx], 4);
548	        lower0 = __shfl_sync(uint32_t(-1), lower0, upper_map[quad_idx] ^ 1, 4);
549	        frag_64b[i].x = __byte_perm(upper0, lower0, selector_upper);
550	        frag_64b[i].y = __byte_perm(upper0, lower0, selector_lower);
551	    }
552	}
